      }
    }
  }),
  virtualView:function(ctx){
    return h("input", {
      "ev-keydown":function(ev){
        ctx.action.getPlugin("tag-input").emitKeydown(ev);
      },
      "ev-keyup":function(ev){
        ctx.action.getPlugin("tag-input").emitKeyup(ev);
      }
    });
